<script setup>
import { ref, watch } from 'vue';
import { api } from '../../services/api';
import SvgIcon from '../SvgIcon.vue';
const props = defineProps({ projectId: String, state: Object });
const emit = defineEmits(['refresh', 'error', 'episodes']);
const plan = ref({ major_events: [], episodes: [] }); const busy = ref(false); const uploading = ref(false); const expanded = ref(0); const eventExpanded = ref(0);
watch(() => props.state, s => {
  plan.value = JSON.parse(JSON.stringify(s?.content?.episodes || s?.content?.major_events ? s.content : { major_events: [], episodes: [] }));
  plan.value.major_events ||= []; plan.value.episodes ||= [];
  if (plan.value.episodes.length) emit('episodes', plan.value.episodes);
}, { immediate: true });
async function generate() { busy.value = true; try { await api.generateStage(props.projectId, 2); emit('refresh'); } catch(e) { emit('error', e.message); } finally { busy.value = false; } }
async function save() { try { const result = await api.saveStage(props.projectId, 2, plan.value); emit('episodes', plan.value.episodes); return result; } catch(e) { emit('error', e.message); throw e; } }
async function uploadEvents(event) { const file = event.target.files[0]; if (!file) return; uploading.value = true; try { await save(); await api.uploadMajorEvents(props.projectId, file); emit('refresh'); } catch(e) { emit('error', e.message); } finally { uploading.value = false; event.target.value = ''; } }
function addEvent() { const index = plan.value.major_events.length; plan.value.major_events.push({ id: `event_${crypto.randomUUID().slice(0, 10)}`, time_order: index + 1, time_label: '', title: '新大事件', description: '', cause: '', consequence: '' }); eventExpanded.value = index; }
function removeEvent(index) { if (!window.confirm('删除这个大事件？相关剧集会保留，但需要重新检查事件关联。')) return; plan.value.major_events.splice(index, 1); orderEvents(); save(); }
function moveEvent(index, direction) { const target = index + direction; if (target < 0 || target >= plan.value.major_events.length) return; [plan.value.major_events[index], plan.value.major_events[target]] = [plan.value.major_events[target], plan.value.major_events[index]]; orderEvents(); eventExpanded.value = target; save(); }
function orderEvents() { plan.value.major_events.forEach((event, i) => event.time_order = i + 1); }
function add() { const number = plan.value.episodes.length + 1; plan.value.episodes.push({ episode_number: number, title: `第 ${number} 集`, major_event_ids: [], timeline_position: '', source_chapters: [], main_plot: '', key_characters: [], main_conflict: '', opening_hook: '', dramatic_highlights: [], climax: '', cliffhanger: '', scene_requirements: [], estimated_duration: 90 }); expanded.value = number - 1; }
function move(index, direction) { const target = index + direction; if (target < 0 || target >= plan.value.episodes.length) return; [plan.value.episodes[index], plan.value.episodes[target]] = [plan.value.episodes[target], plan.value.episodes[index]]; plan.value.episodes.forEach((e, i) => e.episode_number = i + 1); expanded.value = target; save(); }
function merge(index) { if (index >= plan.value.episodes.length - 1) return; const current = plan.value.episodes[index], next = plan.value.episodes[index + 1]; current.title += ` / ${next.title}`; current.main_plot = `${current.main_plot}\n${next.main_plot}`; current.source_chapters = [...(current.source_chapters || []), ...(next.source_chapters || [])]; current.major_event_ids = [...new Set([...(current.major_event_ids || []), ...(next.major_event_ids || [])])]; current.dramatic_highlights = [...(current.dramatic_highlights || []), ...(next.dramatic_highlights || [])]; current.estimated_duration = Number(current.estimated_duration || 90) + Number(next.estimated_duration || 90); plan.value.episodes.splice(index + 1, 1); plan.value.episodes.forEach((e, i) => e.episode_number = i + 1); save(); }
function split(index) { const copy = JSON.parse(JSON.stringify(plan.value.episodes[index])); copy.title += '（下）'; plan.value.episodes[index].title += '（上）'; plan.value.episodes.splice(index + 1, 0, copy); plan.value.episodes.forEach((e, i) => e.episode_number = i + 1); save(); }
function list(value) { return Array.isArray(value) ? value.join('、') : value || ''; }
function setList(target, key, value) { target[key] = value.split(/[、,，\n]/).map(v => v.trim()).filter(Boolean); }
function eventTitles(episode) { return (episode.major_event_ids || []).map(id => plan.value.major_events.find(e => e.id === id)?.title).filter(Boolean).join('、'); }
defineExpose({ save });
</script>

<template>
  <div>
    <section class="timeline-section"><div class="stage-actions"><div><strong>故事大事件时间线</strong><span>只记录改变故事阶段、主角目标或世界局势的大事件，不是单集小冲突。</span></div><div><label class="btn secondary small upload"><SvgIcon name="upload" :size="15" />{{ uploading ? '正在整理…' : '上传事件文档' }}<input type="file" accept=".txt,.md,.docx,.pdf" :disabled="uploading" @change="uploadEvents" hidden /></label><button class="btn secondary small" @click="addEvent"><SvgIcon name="plus" :size="15" />添加大事件</button></div></div>
      <div v-if="!plan.major_events.length" class="timeline-empty">生成剧集规划时，AI 会先从 Story Bible 提取大事件。也可以上传文档补充或改变事件。</div>
      <div v-else class="timeline-list"><article v-for="(event, index) in plan.major_events" :key="event.id" class="event-card"><button class="event-summary" @click="eventExpanded = eventExpanded === index ? -1 : index"><span>{{ String(index + 1).padStart(2, '0') }}</span><div><strong>{{ event.title }}</strong><small>{{ event.time_label || '待明确时间' }} · {{ event.description || '待补充事件内容' }}</small></div><SvgIcon name="chevron" :size="16" /></button><div v-if="eventExpanded === index" class="event-editor"><div class="form-grid"><label>事件名称<input v-model="event.title" /></label><label>时间线位置<input v-model="event.time_label" placeholder="故事开端 / 三年后 / 决战前夜" /></label></div><label>事件完整描述<textarea v-model="event.description" placeholder="发生了什么，为什么属于全书级大事件"></textarea></label><div class="form-grid"><label>前因<textarea v-model="event.cause"></textarea></label><label>后果与影响<textarea v-model="event.consequence"></textarea></label></div><div class="event-actions"><button @click="moveEvent(index, -1)">前移</button><button @click="moveEvent(index, 1)">后移</button><button class="danger" @click="removeEvent(index)">删除</button><button class="btn primary small" @click="save">保存时间线</button></div></div></article></div>
    </section>

    <div class="stage-actions episode-heading"><div><strong>剧集总规划</strong><span>每集明确关联哪些大事件，以及它处于什么时间线。</span></div><div><button class="btn secondary small" @click="add"><SvgIcon name="plus" :size="15" />添加剧集</button><button class="btn primary small" :disabled="busy || uploading" @click="generate"><SvgIcon name="spark" :size="16" />{{ busy ? 'AI 正在提取事件并规划…' : plan.episodes.length ? '重新提取并规划' : '提取大事件并规划' }}</button></div></div>
    <section v-if="!plan.episodes.length" class="empty-content"><SvgIcon name="queue" :size="30" /><h3>还没有剧集规划</h3><p>AI 会先建立全书大事件，再确定每集发生什么、处于哪段时间线。</p><button class="btn primary" :disabled="busy" @click="generate">开始规划</button></section>
    <div v-else class="episode-plan-list"><article v-for="(episode, index) in plan.episodes" :key="index" class="plan-card"><button class="plan-summary" @click="expanded = expanded === index ? -1 : index"><span class="episode-number">{{ String(episode.episode_number).padStart(2, '0') }}</span><span class="plan-title"><strong>{{ episode.title }}</strong><small>{{ episode.timeline_position || eventTitles(episode) || '待关联大事件与时间线' }}</small></span><span class="duration">{{ episode.estimated_duration }} 秒</span><SvgIcon name="chevron" :size="16" /></button><div v-if="expanded === index" class="plan-editor"><div class="form-grid"><label>剧集标题<input v-model="episode.title" /></label><label>预计时长（秒）<input type="number" v-model.number="episode.estimated_duration" /></label></div><div class="form-grid"><label>关联大事件<input :value="list(episode.major_event_ids)" @change="setList(episode, 'major_event_ids', $event.target.value)" placeholder="event_1、event_2" /></label><label>本集时间线<input v-model="episode.timeline_position" placeholder="大事件 X 之后、决战前三天" /></label></div><label>原著章节映射<input :value="list(episode.source_chapters)" @change="setList(episode, 'source_chapters', $event.target.value)" placeholder="第一章、第二章" /></label><label>本集发生了什么<textarea v-model="episode.main_plot"></textarea></label><div class="form-grid"><label>核心冲突<textarea v-model="episode.main_conflict"></textarea></label><label>开场钩子<textarea v-model="episode.opening_hook"></textarea></label></div><label>关键角色<input :value="list(episode.key_characters)" @change="setList(episode, 'key_characters', $event.target.value)" /></label><label>戏剧高光<textarea :value="list(episode.dramatic_highlights)" @change="setList(episode, 'dramatic_highlights', $event.target.value)"></textarea></label><div class="form-grid"><label>高潮<textarea v-model="episode.climax"></textarea></label><label>结尾悬念<textarea v-model="episode.cliffhanger"></textarea></label></div><div class="plan-edit-actions"><button class="text-btn" @click="move(index, -1)">上移</button><button class="text-btn" @click="move(index, 1)">下移</button><button class="text-btn" @click="split(index)">拆分</button><button class="text-btn" @click="merge(index)">与下一集合并</button><button class="btn primary small" @click="save">保存本集</button></div></div></article></div>
  </div>
</template>

<style scoped>
.stage-actions{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.stage-actions>div{display:flex;gap:8px}.stage-actions>div:first-child{display:block}.stage-actions strong{display:block}.stage-actions span{font-size:12px;color:var(--text-secondary)}.upload{cursor:pointer}.timeline-section{background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:18px;margin-bottom:24px}.timeline-empty{padding:24px;border:1px dashed var(--border-strong);border-radius:8px;text-align:center;color:var(--text-secondary);font-size:12px}.timeline-list{display:flex;flex-direction:column;gap:8px}.event-card{border:1px solid var(--border);border-radius:9px;overflow:hidden}.event-summary{display:flex;align-items:center;gap:12px;width:100%;padding:13px;background:transparent;text-align:left;color:var(--text)}.event-summary>span{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:var(--accent-soft);color:var(--accent);font-size:10px}.event-summary>div{flex:1;min-width:0}.event-summary strong,.event-summary small{display:block}.event-summary small{font-size:11px;color:var(--text-secondary);margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.event-editor{padding:16px;border-top:1px solid var(--border);background:#fafbfc}.event-editor label,.plan-editor label{display:block;font-size:12px;font-weight:600;margin:10px 0}.event-editor input,.event-editor textarea,.plan-editor input,.plan-editor textarea{width:100%;margin-top:6px}.event-editor textarea,.plan-editor textarea{min-height:75px}.event-actions{display:flex;gap:12px;align-items:center}.event-actions>button:not(.btn){background:transparent;color:var(--text-secondary);font-size:11px}.event-actions .danger{color:#ad4840!important}.event-actions .btn{margin-left:auto}.episode-heading{margin-top:8px}.empty-content{text-align:center;padding:80px 20px;background:var(--surface);border:1px dashed var(--border-strong);border-radius:12px;color:var(--text-secondary)}.episode-plan-list{display:flex;flex-direction:column;gap:10px}.plan-card{background:var(--surface);border:1px solid var(--border);border-radius:11px;overflow:hidden}.plan-summary{display:grid;grid-template-columns:48px 1fr auto 20px;align-items:center;gap:14px;width:100%;padding:16px;background:transparent;color:var(--text);text-align:left}.episode-number{display:grid;place-items:center;width:40px;height:40px;background:var(--accent-soft);color:var(--accent);border-radius:9px;font-weight:700}.plan-title strong,.plan-title small{display:block}.plan-title small{color:var(--text-secondary);margin-top:4px}.duration{font-size:12px;color:var(--text-secondary)}.plan-editor{padding:20px;border-top:1px solid var(--border);background:#fbfcfd}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.plan-edit-actions{display:flex;align-items:center;gap:12px;margin-top:16px}.plan-edit-actions .btn{margin-left:auto}.text-btn{background:transparent;color:var(--text-secondary);padding:5px;font-size:12px}@media(max-width:650px){.stage-actions{align-items:flex-start;flex-direction:column}.stage-actions>div{flex-wrap:wrap}.plan-summary{grid-template-columns:42px 1fr 18px}.duration{display:none}.form-grid{grid-template-columns:1fr}}
</style>
